import pandas as pd

MAPA_PAIS = {"rd": "República Dominicana", "rep. dom.": "República Dominicana",
             "república dominicana": "República Dominicana", "pr": "Puerto Rico"}


def normalizar_pais(s: pd.Series) -> pd.Series:
    limpio = s.str.strip().str.lower()
    return limpio.map(MAPA_PAIS).fillna(s.str.strip())


def convertir_monto(s: pd.Series) -> pd.Series:
    texto = s.str.replace("RD$", "", regex=False).str.replace(",", "", regex=False).str.strip()
    return pd.to_numeric(texto, errors="coerce")


def convertir_fecha(s: pd.Series) -> pd.Series:
    iso = pd.to_datetime(s, format="%Y-%m-%d", errors="coerce")
    dmy = pd.to_datetime(s, format="%d/%m/%Y", errors="coerce")
    return iso.fillna(dmy)

