import numpy as np
import pandas as pd


def normalizar_telefono(s: pd.Series) -> pd.Series:
    digitos = s.astype("string").str.replace(r"\D", "", regex=True)
    digitos = digitos.where(~((digitos.str.len() == 11) & digitos.str.startswith("1")), digitos.str[1:])
    return digitos.where(digitos.str.len() == 10, np.nan)

