def validar(texto: str) -> dict:
    datos = json.loads(texto)
    if set(datos) != {"categoria", "sentimiento"}:
        raise ValueError(f"Claves inesperadas: {set(datos)}")
    if datos["categoria"] not in CATEGORIAS:
        raise ValueError(f"Categoría fuera de la lista: {datos['categoria']}")
    if datos["sentimiento"] not in {"positivo", "neutro", "negativo"}:
        raise ValueError(f"Sentimiento inválido: {datos['sentimiento']}")
    return datos

