import hashlib
import json
import time
from pathlib import Path

CACHE = Path("cache_clasificacion.jsonl")
hechos = {}
if CACHE.exists():
    for linea in CACHE.read_text(encoding="utf-8").splitlines():
        registro = json.loads(linea)
        hechos[registro["hash"]] = registro["resultado"]


def clasificar_con_cache(texto: str) -> dict:
    clave = hashlib.sha256(texto.encode("utf-8")).hexdigest()
    if clave in hechos:
        return hechos[clave]
    for intento in range(4):
        try:
            resultado = clasificar(texto)
            break
        except anthropic.APIError:
            time.sleep(2 ** intento)
    else:
        resultado = {"categoria": "revisar", "sentimiento": "revisar"}
    hechos[clave] = resultado
    with CACHE.open("a", encoding="utf-8") as f:
        f.write(json.dumps({"hash": clave, "resultado": resultado}, ensure_ascii=False) + "\n")
    return resultado

