cliente = anthropic.Anthropic()
MOTIVOS = {"devolución", "retraso", "cobro", "otro"}
SISTEMA = ('Extrae datos de un correo de cliente. Responde SOLO con JSON con las claves '
           '"numero_pedido" (texto o null), "monto" (número o null) y '
           '"motivo" (devolución, retraso, cobro u otro).')


def extraer_pedido(texto: str) -> dict:
    r = cliente.messages.create(model=MODELO, max_tokens=150, temperature=0,
                                system=SISTEMA, messages=[{"role": "user", "content": texto}])
    try:
        d = json.loads(r.content[0].text)
        assert set(d) == {"numero_pedido", "monto", "motivo"}
        assert d["numero_pedido"] is None or isinstance(d["numero_pedido"], str)
        assert d["monto"] is None or isinstance(d["monto"], (int, float))
        assert d["motivo"] in MOTIVOS
        return d
    except (json.JSONDecodeError, AssertionError):
        return {"numero_pedido": None, "monto": None, "motivo": "revisar"}

