import re


def cifras_no_rastreables(texto: str, cifras: dict) -> set[float]:
    permitidos = set()
    for v in cifras.values():
        if isinstance(v, (int, float)):
            permitidos |= {float(v), float(round(v, 1)), float(round(v))}
    encontrados = re.findall(r"\d[\d,]*(?:\.\d+)?", texto)
    numeros = {float(n.replace(",", "")) for n in encontrados}
    return numeros - permitidos

